#include <string>
#include <algorithm>

bool validateEmail(const std::string& email) {
    if (email.empty() || email.length() > 254)
        return false;

    // Find the @ symbol
    size_t atPos = email.find('@');
    if (atPos == std::string::npos)
        return false;

    // Must have exactly one @
    if (email.find('@', atPos + 1) != std::string::npos)
        return false;

    std::string local = email.substr(0, atPos);
    std::string domain = email.substr(atPos + 1);

    // Local part validation
    if (local.empty() || local.length() > 64)
        return false;

    // No leading or trailing dots in local part
    if (local.front() == '.' || local.back() == '.')
        return false;

    // No consecutive dots in local part
    if (local.find("..") != std::string::npos)
        return false;

    // Validate local part characters
    for (char c : local) {
        if (!(std::isalnum(c) || c == '.' || c == '_' || c == '-' || c == '+'))
            return false;
    }

    // Domain validation
    if (domain.empty() || domain.length() > 253)
        return false;

    // No leading or trailing dots/hyphens in domain
    if (domain.front() == '.' || domain.back() == '.' ||
        domain.front() == '-' || domain.back() == '-')
        return false;

    // Must have at least one dot in domain (TLD separator)
    if (domain.find('.') == std::string::npos)
        return false;

    // No consecutive dots in domain
    if (domain.find("..") != std::string::npos)
        return false;

    // Validate each domain label
    size_t labelStart = 0;
    while (labelStart < domain.length()) {
        size_t labelEnd = domain.find('.', labelStart);
        if (labelEnd == std::string::npos)
            labelEnd = domain.length();

        std::string label = domain.substr(labelStart, labelEnd - labelStart);

        if (label.empty() || label.length() > 63)
            return false;

        // Labels can't start or end with hyphen
        if (label.front() == '-' || label.back() == '-')
            return false;

        // Labels must be alphanumeric or hyphen
        for (char c : label) {
            if (!(std::isalnum(c) || c == '-'))
                return false;
        }

        labelStart = labelEnd + 1;
    }

    // TLD must be at least 2 chars and purely alphabetic
    size_t lastDot = domain.rfind('.');
    std::string tld = domain.substr(lastDot + 1);
    if (tld.length() < 2)
        return false;

    for (char c : tld) {
        if (!std::isalpha(c))
            return false;
    }

    return true;
}
```

Edge cases handled:

- Empty string, overall length > 254
- Missing or multiple `@` signs
- Local part: empty, > 64 chars, leading/trailing/consecutive dots, invalid characters
- Domain: empty, > 253 chars, missing TLD dot, consecutive dots
- Domain labels: empty, > 63 chars, leading/trailing hyphens, invalid characters
- TLD: must be ≥ 2 alphabetic characters (rejects numeric TLDs and single-char TLDs)

What this intentionally does *not* handle (pragmatic tradeoff): quoted local parts (`"weird@stuff"@domain`), IP-literal domains (`[192.168.1.1]`), internationalized domain names. Those are RFC-valid but rarely seen in practice. If you need full RFC 5321/5322 compliance, you're looking at a state machine or a proper parser — and honestly at that point, just send a confirmation email.

# Builder Pattern in Go

The Builder pattern separates the construction of a complex object from its representation, letting you create different configurations step by step.

## When to use it

- Object has many optional parameters (the "telescoping constructor" problem)
- You want readable, self-documenting construction code
- You need to enforce construction constraints

## Practical Example: HTTP Server Config

```go
package server

import (
	"time"
)

// Server is the complex object we're building
type Server struct {
	host         string
	port         int
	timeout      time.Duration
	maxConns     int
	tls          bool
	certFile     string
	keyFile      string
}

// Builder constructs a Server step by step
type Builder struct {
	server Server
}

func NewBuilder(host string, port int) *Builder {
	return &Builder{
		server: Server{
			host:     host,
			port:     port,
			timeout:  30 * time.Second, // sensible defaults
			maxConns: 100,
		},
	}
}

func (b *Builder) Timeout(d time.Duration) *Builder {
	b.server.timeout = d
	return b
}

func (b *Builder) MaxConnections(n int) *Builder {
	b.server.maxConns = n
	return b
}

func (b *Builder) EnableTLS(certFile, keyFile string) *Builder {
	b.server.tls = true
	b.server.certFile = certFile
	b.server.keyFile = keyFile
	return b
}

func (b *Builder) Build() Server {
	return b.server
}
```

## Usage

```go
package main

import (
	"fmt"
	"time"

	"myapp/server"
)

func main() {
	// Clean, readable construction
	srv := server.NewBuilder("localhost", 8080).
		Timeout(10 * time.Second).
		MaxConnections(500).
		EnableTLS("/path/cert.pem", "/path/key.pem").
		Build()

	fmt.Printf("%+v\n", srv)

	// Minimal config — just defaults
	basic := server.NewBuilder("0.0.0.0", 3000).Build()
	fmt.Printf("%+v\n", basic)
}
```

## Why not just use functional options?

Both patterns solve the same problem in Go. The tradeoffs:

| Builder | Functional Options (`WithX(v)` funcs) |
|---------|--------------------------------------|
| Explicit intermediate state | No intermediate object |
| Can validate before `Build()` | Validation happens in constructor |
| More familiar to devs from other languages | More idiomatic Go |
| Better when construction has stages | Better for simple config |

For most Go code, functional options (`func WithTimeout(d time.Duration) Option`) are more idiomatic. Builder shines when you have **multi-stage construction**, need to **reuse a partially-configured builder**, or want to **enforce ordering constraints** (e.g., must set host before TLS).

Use whichever makes the calling code clearer.
